import { Component, h, Prop, Element, Event, EventEmitter, State, Host, Fragment, Watch } from '@stencil/core';
import classnames from 'classnames';
import { Slot, Slots, Uncontrollable, Vue2ValueFix } from '@src/framework/decorators';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { inputNumberMessages } from '@fe-infra/keystone-locales';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { BigIntDecimal, toFixed, formatToLocalizedNumber, parseLocalizedNumber, getNumberPrecision } from './utils';
import { DetailArgs } from '@src/shared/dom/event-utils';
import { t } from '@src/shared/i18n';
import { InputNumberAction } from './types';
import { KsIconChevronDown, KsIconChevronUp, KsIconMinus, KsIconPlus } from '@fe-infra/keystone-icons-stencil';

const prefix = 'input-number';

/**
 * @slot prefix - Slot for content to be displayed before the input field.
 * @slot suffix - Slot for content to be displayed after the input field.
 * @part input - The native input element exported from the internal `ks-input`.
 */
@Component({
  tag: 'ks-input-number',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsInputNumber extends FormBaseComponent<string | number> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  protected static controlledModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsInputNumberElement;
  private inputEl!: HTMLKsInputElement;
  /** The component that display in the suffix area */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;

  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  /** Whether the input field should be automatically focused when the page loads. */
  @Prop() autoFocus?: boolean;
  /** Whether the input field is read-only. When `true`, the input field cannot be edited by the user. */
  @Prop() readOnly?: boolean;
  /** The value of the input field, which will be of type `number` or `string` based on the `valueType` setting. When the input field is empty, the value is always `null`. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: string | null;
  /** The default value of the input field when it is first rendered. */
  @Prop() defaultValue?: string | null;

  @State() _value?: BigIntDecimal | null;
  @State() _defaultValue?: BigIntDecimal | null;
  @Uncontrollable('_value', '_defaultValue', '_ksChange') @State() internalValueState!: BigIntDecimal;
  /** The size of the input field. Possible values are "sm" and "md". */
  @Prop() size: 'sm' | 'md' = 'md';
  /** Placeholder text displayed in the input field when it is empty. */
  @Prop() placeholder?: string;
  /** Indicates whether the input field is disabled. When `true`, the input field is disabled and cannot be interacted with. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** Indicates whether the input field can be cleared by the user. When `true`, a clear button is displayed to clear the input value. */
  @Prop() clearable = false;
  /** The status of the input field. Possible values include `"default"`, `"warning"` and `"error"`. */
  @Prop() @FormContextValueReconcile() status?: 'default' | 'warning' | 'error';
  /** The minimum value that can be entered in the input field. */
  @Prop() min = -Infinity;
  /** The maximum value that can be entered in the input field. */
  @Prop() max = Infinity;
  /** The number of decimal places to which the input value is rounded. */
  @Prop() precision?: number;
  /** Explicitly sets the visibility of the increment/decrement control buttons. If this prop is not set (i.e., `undefined`), the visibility defaults to showing controls for the "sm" size and hiding them for the "md" size. */
  @Prop() controls?: boolean | { step?: number } = false;
  get showControls() {
    return this.controls === true || typeof this.controls === 'object';
  }
  get step() {
    if (typeof this.controls === 'boolean') {
      return 1;
    } else {
      return this.controls?.step || 1;
    }
  }
  /** Custom event triggered when the value of the input field changes. The event detail contains the new value, which can be a `number` or `string` based on the `valueType` prop. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[string, { reason: 'type' | 'blur' | 'step' }]>
  >;
  /** Custom event triggered when the clear button is clicked to clear the input number. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;

  /**
   * Custom formatter functions for input value processing.
   * - `parse`: A function used to parse the text in the input field into a numerical value in real-time. By default, this function parses based on numeric localization rules.
   * - `format`: A function used to format the numerical value into a localized string. By default, this function formats based on numeric localization rules.
   */
  @Prop() formatters?: {
    parse?: (value: string) => string;
    format?: (value: string, precision?: number) => string;
  };
  get parse() {
    return this.formatters?.parse || parseLocalizedNumber;
  }
  get format() {
    return (value: string, precision?: number) => {
      if (this.formatters?.format) {
        return this.formatters.format(value, precision);
      } else {
        if (!this._userTyping) {
          const precision = this.getPrecision(value, this._userTyping);
          return formatToLocalizedNumber(value, precision);
        } else {
          return value;
        }
      }
    };
  }

  @Watch('value')
  handleValueChange() {
    this._value = this.value !== undefined && this.value !== null ? new BigIntDecimal(this.value) : undefined;
  }
  @Watch('defaultValue')
  handleDefaultValueChange() {
    this._defaultValue =
      this.defaultValue !== undefined && this.defaultValue !== null ? new BigIntDecimal(this.defaultValue) : undefined;
  }
  protected _ksChange = {
    emit: (value: BigIntDecimal | null) => {
      sendActionTracking(this.el, { eventType: 'change', componentParams: { value: value?.toString() || '' } });

      const reason: 'step' | 'type' | 'blur' = this._onStep ? 'step' : this._userTyping ? 'type' : 'blur';
      this.ksChange.emit(DetailArgs(value?.toString() || '', { reason }));
    },
  };

  /** handle cursor selection range for input number */
  private selectionInfo?: {
    start: number;
    end: number;
    value: string;
    beforeText: string;
    afterText: string;
  };
  private recordCursor = (value: string) => {
    const {
      selection: [start, end],
    } = this.inputEl as HTMLKsInputElement & {
      selection: [number, number];
    };
    const beforeText = value.substring(0, start);
    const afterText = value.substring(end);
    this.selectionInfo = {
      start,
      end,
      value,
      beforeText,
      afterText,
    };
  };
  private restoreCursor = () => {
    if (this.selectionInfo) {
      try {
        const { internalValueState: value } = this.inputEl as HTMLKsInputElement & {
          internalValueState: string;
        };
        const { beforeText, afterText, start } = this.selectionInfo;
        let startPos = value.length;
        if (value.startsWith(beforeText)) {
          startPos = beforeText.length;
        } else if (value.endsWith(afterText)) {
          startPos = value.length - afterText.length;
        } else {
          const beforeLastChar = beforeText[start - 1]!;
          const newIndex = value.indexOf(beforeLastChar, start - 1);
          if (newIndex !== -1) {
            startPos = newIndex + 1;
          }
        }
        this.inputEl.setSelectionRange(startPos, startPos);
      } catch (e) {
        console.warn('Something warning of cursor restore. Please fire issue about this: ', e);
      }
    }
  };

  @State() inputValue = '';

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  private getDecimalIfValidate = (value: number) => {
    const decimal = new BigIntDecimal(value);
    return decimal.isInvalidate() ? null : decimal;
  };

  get maxDecimal() {
    return this.getDecimalIfValidate(this.max);
  }
  get minDecimal() {
    return this.getDecimalIfValidate(this.min);
  }
  private getRangeValue = (target: BigIntDecimal) => {
    if (this.maxDecimal && !target.lessEquals(this.maxDecimal)) {
      return this.maxDecimal;
    }
    if (this.minDecimal && !this.minDecimal.lessEquals(target)) {
      return this.minDecimal;
    }
    return null;
  };

  private handleBlur = () => {
    this._userTyping = false;
    this.flushInputValue();
    sendActionTracking(this.el, { eventType: 'blur' });
  };

  private handleFocus = () => {
    sendActionTracking(this.el, { eventType: 'focus' });
  };

  private handleInput = ({ detail: inputStr }: { detail: string }) => {
    this._userTyping = true;
    this.recordCursor(inputStr);
    this.inputValue = inputStr;

    const finalValue = this.parse(inputStr);
    const finalDecimal = new BigIntDecimal(finalValue);

    if (!finalDecimal.isNaN()) {
      this.triggerValueUpdate(finalDecimal);
    }
  };

  private flushInputValue = () => {
    const parsedValue = new BigIntDecimal(this.parse(this.inputValue));
    let formatValue: BigIntDecimal | null = null;

    if (!parsedValue.isNaN()) {
      formatValue = this.triggerValueUpdate(parsedValue);
    } else if (this.internalValueState !== undefined) {
      formatValue = this.triggerValueUpdate(this.internalValueState);
    }

    if (this.value !== undefined) {
      // Reset back with controlled value first
      this.setInputValue(this.internalValueState);
    } else if (formatValue === null) {
      this.setInputValue(this.internalValueState);
    } else if (!formatValue.isNaN()) {
      // Reset input back since no validate value
      this.setInputValue(formatValue);
    }
  };

  private getPrecision(numStr: string, userTyping: boolean) {
    if (userTyping) {
      return undefined;
    }
    return this.precision !== undefined && this.precision >= 0 ? this.precision : getNumberPrecision(numStr);
  }

  private _userTyping = false;
  private _onStep = false;
  private triggerValueUpdate(newValue: BigIntDecimal) {
    let updateValue = newValue;

    let isRangeValidate = !this.getRangeValue(updateValue) || updateValue.isEmpty();

    if (!updateValue.isEmpty() && !this._userTyping) {
      updateValue = this.getRangeValue(updateValue) || updateValue;
      isRangeValidate = true;
    }

    if (!this.readOnly && !this.disabled && isRangeValidate) {
      const numStr = updateValue.toString();
      const precision = this.getPrecision(numStr, this._userTyping);
      if (precision !== undefined && precision >= 0) {
        updateValue = new BigIntDecimal(toFixed(numStr, '.', precision));

        // When to fixed. The value may out of min & max range.
        // 4 in [0, 3.8] => 3.8 => 4 (toFixed)
        if (this.getRangeValue(updateValue)) {
          updateValue = new BigIntDecimal(toFixed(numStr, '.', precision, true));
        }
      }
      // trigger event
      if (!this.internalValueState || !updateValue.equals(this.internalValueState)) {
        this.internalValueState = updateValue;

        // Reformat input if value is not controlled
        if (this.value === undefined) {
          this.setInputValue(updateValue);
        }
      }
      return updateValue;
    }
    return this.internalValueState || null;
  }

  private handleUpdateFromControls = (type: InputNumberAction) => {
    this._userTyping = false;
    if (this.disabled) {
      return;
    }
    let stepDecimal = new BigIntDecimal(this.step);
    if (type === 'decrease') {
      stepDecimal = stepDecimal.negate();
    }

    const target = (this.internalValueState || new BigIntDecimal(0)).add(stepDecimal.toString());
    this._onStep = true;
    this.triggerValueUpdate(target);
    this._onStep = false;

    this.inputEl.focus();
  };

  private renderOutsetControls = () => {
    const disabledUp =
      (this.internalValueState && this.maxDecimal?.lessEquals(this.internalValueState)) || this.disabled;
    const disabledDown = (this.minDecimal && this.internalValueState?.lessEquals(this.minDecimal)) || this.disabled;
    return (
      this.showControls && (
        <Fragment>
          <span slot="_internal-controls-end" class={classnames(`${prefix}__out-ctl-btn`)}>
            <span
              class={classnames(`${prefix}__out-ctl-btn-up`, {
                [`${prefix}__out-ctl-btn-up--disabled`]: disabledUp,
              })}
              onClick={() => !disabledUp && this.handleUpdateFromControls('increase')}
              data-testid="ks-input-number-index-i5voqh"
            >
              <KsIconChevronUp size="14" />
            </span>
            <span
              class={classnames(`${prefix}__out-ctl-btn-down`, {
                [`${prefix}__out-ctl-btn-down--disabled`]: disabledDown,
              })}
              onClick={() => !disabledDown && this.handleUpdateFromControls('decrease')}
              data-testid="ks-input-number-index-ew1ATE"
            >
              <KsIconChevronDown size="14" />
            </span>
          </span>
        </Fragment>
      )
    );
  };

  private renderInsetControls = () => {
    const disabledUp =
      (this.internalValueState && this.maxDecimal?.lessEquals(this.internalValueState)) || this.disabled;
    const disabledDown = (this.minDecimal && this.internalValueState?.lessEquals(this.minDecimal)) || this.disabled;
    return (
      (typeof this.showControls !== 'boolean' || this.showControls) && (
        <Fragment>
          {/* 加按钮 */}
          <span
            slot="_internal-controls-end"
            class={classnames(`${prefix}__controls-btn ${prefix}__controls-btn-end`, {
              [`${prefix}__controls-btn--disabled`]: disabledUp,
            })}
            onClick={() => this.handleUpdateFromControls('increase')}
            data-testid="ks-input-number-index-oevemz"
          >
            <KsIconPlus size="14" />
          </span>
          {/* 减按钮 */}
          <span
            slot="_internal-controls-start"
            class={classnames(`${prefix}__controls-btn ${prefix}__controls-btn-start`, {
              [`${prefix}__controls-btn--disabled`]: disabledDown,
            })}
            onClick={() => this.handleUpdateFromControls('decrease')}
            data-testid="ks-input-number-index-2arrMJ"
          >
            <KsIconMinus size="14" />
          </span>
        </Fragment>
      )
    );
  };

  private setInputValue(value: BigIntDecimal) {
    let valueStr = '';
    if (value) {
      valueStr = value.isInvalidate() ? value.toString(false) : value.toString(!this._userTyping);
    }
    this.inputValue = this.format(valueStr, this.getPrecision(valueStr, this._userTyping));
  }

  @Watch('internalValueState')
  handleInternalValueStateChange() {
    this.setInputValue(this.internalValueState);
  }

  componentWillLoad() {
    this.handleDefaultValueChange();
    this.handleValueChange();
  }

  componentDidRender() {
    const syncInputValue = () => {
      if (this.inputValue !== this.inputEl.value) {
        this.inputEl.value = this.inputValue;
        this.restoreCursor();
      }
    };

    // istanbul ignore next
    syncInputValue();
  }

  render() {
    return (
      <Host class="KsInputNumber">
        <ks-input
          exportparts="input"
          class={classnames(prefix, `${prefix}__has-controls`)}
          type="text"
          ref={(inputRef) => (this.inputEl = inputRef!)}
          readOnly={this.readOnly}
          disabled={this.disabled}
          clearable={this.clearable}
          status={this.status}
          placeholder={this.placeholder || t(inputNumberMessages.placeholder)}
          onKsChange={this.handleInput}
          onKsClear={() => this.ksClear.emit()}
          onBlur={this.handleBlur}
          onFocus={this.handleFocus}
          data-testid="ks-input-number-index-sX1fTc"
        >
          {/* 输入框透传slot */}
          {this.prefixSlot && <slot slot="prefix" name="prefix"></slot>}
          {this.suffixSlot && <slot slot="suffix" name="suffix"></slot>}
          {/* 输入框操作 */}
          {this.size === 'md' ? this.renderOutsetControls() : this.renderInsetControls()}
        </ks-input>
      </Host>
    );
  }
}
